  async function healthView() { const h=await api("/api/system/health"); const rows=Object.entries(h.components||{}).map(([k,v])=>`<tr><td><strong>${esc(label(k))}</strong></td><td>${badge(v)}</td><td>${fmt(h.checkedAt)}</td></tr>`); return intro()+stats([["Overall status",h.status]])+table(["Service","Status","Checked"],rows,"No health information returned."); }
  async function detailsView() { const id=new URLSearchParams(location.search).get("id"); if(!id) return intro()+empty("Choose a complaint from the complaint list."); const c=await api(`/api/complaints/${encodeURIComponent(id)}`); const history=(c.statusHistory||[]).map(h=>`<tr><td>${esc(label(h.previousStatus||"Created"))}</td><td>${esc(label(h.newStatus))}</td><td>${esc(h.reason)}</td><td>${fmt(h.changedAt)}</td></tr>`);const evidence=(c.evidence||[]).map(e=>`<tr><td>${esc(e.fileName)}</td><td>${esc(e.mimeType)}</td><td>${esc(Math.ceil(e.sizeBytes/1024))} KB</td><td><a class="btn btn-secondary btn-sm" href="${baseUrl}/api/evidence/${encodeURIComponent(e.id)}/download">Download</a>${role==="super_admin"?` <button class="btn btn-danger btn-sm" data-delete-evidence="${esc(e.id)}">Delete</button>`:""}</td></tr>`);const responses=(c.responses||[]).map(r=>`<article class="response-message ${r.isStaffResponse?"staff-response":"student-response"}"><div><strong>${r.isStaffResponse?"Staff response":"Complaint owner"}</strong><time>${fmt(r.createdAt)}</time></div><p>${esc(r.body)}</p></article>`).join("")||'<div class="empty-state"><p>No public responses have been sent yet.</p></div>';const actions=role!=="department_officer"?`<div class="page-actions action-gap"><button class="btn btn-secondary" data-complaint-status>Change status</button><button class="btn btn-secondary" data-complaint-priority>Change priority</button><button class="btn btn-secondary" data-internal-note>Add internal note</button></div>`:`<div class="page-actions action-gap"><button class="btn btn-secondary" data-complaint-status>Change status</button><button class="btn btn-secondary" data-internal-note>Add internal note</button></div>`; return intro()+`<section class="detail-hero"><div><small>${esc(c.complaintId)}</small><h2>${esc(c.title)}</h2><div>${badge(c.status)} ${badge(c.priority)}</div>${actions}</div></section><section class="dash-card"><h3>Description</h3><p>${esc(c.description)}</p><div class="info-grid"><div class="info-item"><small>Department</small><strong>${esc(c.department)}</strong></div><div class="info-item"><small>Category</small><strong>${esc(c.category)}</strong></div><div class="info-item"><small>Created</small><strong>${fmt(c.createdAt)}</strong></div><div class="info-item"><small>Evidence</small><strong>${(c.evidence||[]).length}</strong></div></div></section><section class="dash-card stack-top"><div class="card-head"><h3>Public responses to complaint owner</h3></div><div class="response-thread">${responses}</div><form id="complaintResponseForm" class="response-form"><label class="field"><span>Response to complaint owner</span><textarea name="body" rows="5" maxlength="10000" placeholder="Write a clear response that the student will see..." required></textarea></label><div class="form-footer"><button class="btn btn-primary" type="submit">Send response to owner</button></div></form></section><section class="dash-card stack-top"><div class="card-head"><h3>Complaint history</h3></div>${table(["Previous status","New status","Reason","Changed"],history,"No history found.")}</section><section class="dash-card stack-top"><div class="card-head"><h3>Attached evidence</h3></div>${table(["File","Type","Size","Action"],evidence,"No evidence attached.")}</section>`; }
  async function formView(admin) { const departments=await api("/api/departments"); return intro()+`<section class="dash-card form-card"><form id="staffForm"><div id="staffFormMessage" class="form-feedback" role="alert" aria-live="polite" hidden></div><div class="form-grid"><label class="field"><span>First name</span><input name="firstName" required maxlength="80"></label><label class="field"><span>Last name</span><input name="lastName" required maxlength="80"></label><label class="field"><span>Staff email</span><input type="email" name="email" required autocomplete="off" placeholder="officer@umat.edu.gh"></label><label class="field"><span>Staff ID</span><input name="staffId" required maxlength="32" pattern="[A-Za-z0-9-]+" placeholder="e.g. UMAT-FIN-003"><small>Use letters, numbers and hyphens only.</small></label><label class="field"><span>Phone number</span><input type="tel" name="phoneNumber" required autocomplete="tel" placeholder="e.g. +233 24 000 0000"></label><label class="field"><span>Role</span><input value="${admin?"Administrator":"Department Officer"}" disabled></label><label class="field full"><span>Administrative Unit</span><select name="departmentId" ${admin?"":"required"}><option value="">${admin?"No administrative unit":"Select administrative unit"}</option>${departments.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join("")}</select></label><label class="field full"><span>Temporary password</span><input type="password" name="temporaryPassword" required minlength="12" maxlength="128" autocomplete="new-password" placeholder="Enter a strong temporary password"><small>At least 12 characters with uppercase, lowercase, number and symbol.</small></label></div><div class="form-footer"><button class="btn btn-primary" type="submit">Create account</button></div><input type="hidden" name="role" value="${admin?"Admin":"DepartmentOfficer"}"></form></section>`; }

  async function content() {
    if (["department-dashboard","admin-dashboard","super-admin-dashboard"].includes(page)) return dashboardView();
    if (["all-complaints","assigned-complaints","assign-complaints","escalated-complaints","responses","evidence"].includes(page)) { const q="?page=1&pageSize=50"; const d=await api(`/api/complaints${q}`); if(page==="escalated-complaints") d.items=(d.items||[]).filter(x=>String(x.status).toLowerCase()==="escalated"); return complaintsView(d); }
    if(page==="complaint-details") return detailsView();
    if(["manage-users","manage-administrators","administrative-unit-accounts"].includes(page)) return usersView();
    if(page==="roles-permissions") return permissionsView();
    if(page==="manage-departments") return simpleList("/api/departments",["Code","Administrative Unit","Email","Status"],d=>`<tr><td>${esc(d.code)}</td><td><strong>${esc(d.name)}</strong></td><td>${esc(d.contactEmail)}</td><td>${badge(d.isActive?"Active":"Inactive")}</td></tr>`,"No administrative units found.");
    if(page==="complaint-categories") return simpleList("/api/categories",["Category","Description","Priority","Status"],c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.description)}</td><td>${badge(c.defaultPriority)}</td><td>${badge(c.isActive?"Active":"Inactive")}</td></tr>`,"No complaint categories found.");
    if(["reports","department-reports"].includes(page)) return reportView();
    if(page==="notifications") return notificationsView();
    if(["audit-logs","system-audit-logs"].includes(page)) return auditView();
    if(page==="profile") return profileView(); if(page==="change-password") return passwordView();
    if(page==="signature-initials") return signatureSettingsView();
    if(["system-settings","security-settings","anonymous-complaint-settings","notification-settings","data-retention"].includes(page)) return settingsView();
    if(page==="backup-restore") return simpleList("/api/system/backups",["Reference","Status","Created","Completed","Size"],b=>`<tr><td><strong>${esc(b.reference)}</strong></td><td>${badge(b.status)}</td><td>${fmt(b.createdAt)}</td><td>${fmt(b.completedAt)}</td><td>${b.sizeBytes == null?"—":esc(`${Math.round(b.sizeBytes/1024/1024)} MB`)}</td></tr>`,"No backups found.");
    if(page==="active-sessions") return simpleList("/api/system/sessions",["User ID","IP address","Created","Last seen","Expires"],s=>`<tr><td>${esc(s.userId)}</td><td>${esc(s.ipAddress)}</td><td>${fmt(s.createdAt)}</td><td>${fmt(s.lastSeenAt)}</td><td>${fmt(s.expiresAt)}</td></tr>`,"No active sessions found.");
    if(page==="system-health") return healthView();
    if(page==="create-officer") return formView(false); if(page==="create-admin") return formView(true);
    if(page==="announcements") return announcementView();
    return intro()+empty("No database endpoint is configured for this page.");
  }

