    const announcementForm=document.querySelector("#announcementForm"),announcementDialog=document.querySelector("#announcementPreview");
    const announcementPayload=(draft=false)=>{const data=new FormData(announcementForm);return {title:String(data.get("title")||"").trim(),message:String(data.get("message")||"").trim(),category:data.get("category"),priority:data.get("priority"),everyone:data.get("everyone")==="on",recipientRoles:data.getAll("recipientRoles"),departmentId:data.get("departmentId")||null,studentLevel:data.get("studentLevel")||null,userIds:[],deliveryChannels:data.getAll("deliveryChannels"),publishAt:data.get("publishAt")?new Date(data.get("publishAt")).toISOString():null,expiresAt:data.get("expiresAt")?new Date(data.get("expiresAt")).toISOString():null,requireAcknowledgement:data.get("requireAcknowledgement")==="on",saveAsDraft:draft};};
